//! Single sign-on (D-063) end to end: a fake OpenID Connect provider
//! (discovery, JWKS, device authorization, token endpoint; RS256 tokens
//! signed with a throwaway key generated by `openssl` per run), a real
//! coordinator configured for it, a real worker, and `ant login --sso`.

use base64::Engine as _;
use std::io::{BufRead as _, BufReader, Read as _, Write as _};
use std::net::TcpListener;
use std::path::{Path, PathBuf};
use std::process::{Child, Command, Stdio};
use std::sync::Arc;
use std::sync::atomic::{AtomicUsize, Ordering};

struct TempDir(PathBuf);

impl TempDir {
    fn new(name: &str) -> Self {
        let unique = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .expect("clock")
            .as_nanos();
        let path =
            std::env::temp_dir().join(format!("ant-sso-{name}-{}-{unique}", std::process::id()));
        std::fs::create_dir_all(&path).expect("temp dir");
        Self(path)
    }
}

impl Drop for TempDir {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.0);
    }
}

struct Guard(Child);

impl Drop for Guard {
    fn drop(&mut self) {
        let _ = self.0.kill();
        let _ = self.0.wait();
    }
}

fn b64(bytes: &[u8]) -> String {
    base64::engine::general_purpose::URL_SAFE_NO_PAD.encode(bytes)
}

fn now() -> u64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .expect("clock")
        .as_secs()
}

/// An RS256 ID token for `email`, signed with `key`.
fn id_token(
    key: &ring::signature::RsaKeyPair,
    issuer: &str,
    audience: &str,
    email: &str,
    exp: u64,
) -> String {
    let header = b64(br#"{"alg":"RS256","typ":"JWT","kid":"k1"}"#);
    let claims = b64(serde_json::json!({
        "iss": issuer, "aud": audience, "email": email, "email_verified": true,
        "sub": email, "iat": now(), "exp": exp,
    })
    .to_string()
    .as_bytes());
    let message = format!("{header}.{claims}");
    let mut signature = vec![0u8; key.public().modulus_len()];
    key.sign(
        &ring::signature::RSA_PKCS1_SHA256,
        &ring::rand::SystemRandom::new(),
        message.as_bytes(),
        &mut signature,
    )
    .expect("sign");
    format!("{message}.{}", b64(&signature))
}

struct Provider {
    base: String,
    refreshes: Arc<AtomicUsize>,
}

fn fake_provider(key: Arc<ring::signature::RsaKeyPair>, modulus: Vec<u8>) -> Provider {
    let listener = TcpListener::bind("127.0.0.1:0").expect("bind");
    let base = format!("http://{}", listener.local_addr().expect("address"));
    let refreshes = Arc::new(AtomicUsize::new(0));
    let polls = Arc::new(AtomicUsize::new(0));
    let (issuer, counted) = (base.clone(), refreshes.clone());
    std::thread::spawn(move || {
        for stream in listener.incoming() {
            let Ok(mut stream) = stream else { continue };
            let mut reader = BufReader::new(stream.try_clone().expect("clone"));
            let mut line = String::new();
            if reader.read_line(&mut line).is_err() || line.is_empty() {
                continue;
            }
            let path = line.split_whitespace().nth(1).unwrap_or("").to_owned();
            let mut length = 0usize;
            loop {
                let mut header = String::new();
                reader.read_line(&mut header).expect("header");
                let header = header.trim_end().to_ascii_lowercase();
                if header.is_empty() {
                    break;
                }
                if let Some(value) = header.strip_prefix("content-length:") {
                    length = value.trim().parse().unwrap_or(0);
                }
            }
            let mut body = vec![0u8; length];
            reader.read_exact(&mut body).expect("body");
            let form = String::from_utf8_lossy(&body).into_owned();
            let (status, answer) = match path.as_str() {
                "/.well-known/openid-configuration" => (
                    200,
                    serde_json::json!({
                        "issuer": issuer, "jwks_uri": format!("{issuer}/jwks"),
                        "device_authorization_endpoint": format!("{issuer}/device"),
                        "token_endpoint": format!("{issuer}/token"),
                    }),
                ),
                "/jwks" => (
                    200,
                    serde_json::json!({ "keys": [{
                        "kty": "RSA", "kid": "k1", "use": "sig", "alg": "RS256",
                        "n": b64(&modulus), "e": "AQAB",
                    }]}),
                ),
                "/device"
                    if form.contains("client_id=ant-test")
                        && form.contains("scope=openid%20email") =>
                {
                    (
                        200,
                        serde_json::json!({
                            "device_code": "device-123", "user_code": "ABCD-EFGH",
                            "verification_uri": format!("{issuer}/activate"), "interval": 1, "expires_in": 60,
                        }),
                    )
                }
                "/token" if form.contains("device_code=device-123") => {
                    // The developer is still signing in the first time Ant asks.
                    if polls.fetch_add(1, Ordering::SeqCst) == 0 {
                        (400, serde_json::json!({ "error": "authorization_pending" }))
                    } else {
                        // Expires within Ant's renewal window: the next use refreshes.
                        (
                            200,
                            serde_json::json!({
                                "id_token": id_token(&key, &issuer, "ant-test", "dev@acme.dev", now() + 90),
                                "refresh_token": "refresh/1", "token_type": "Bearer",
                            }),
                        )
                    }
                }
                "/token"
                    if form.contains("grant_type=refresh_token")
                        && form.contains("refresh_token=refresh%2F1") =>
                {
                    counted.fetch_add(1, Ordering::SeqCst);
                    (
                        200,
                        serde_json::json!({
                            "id_token": id_token(&key, &issuer, "ant-test", "dev@acme.dev", now() + 3600),
                        }),
                    )
                }
                _ => (400, serde_json::json!({ "error": "invalid_request" })),
            };
            let answer = answer.to_string();
            let _ = write!(
                stream,
                "HTTP/1.1 {status} X\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{answer}",
                answer.len()
            );
        }
    });
    Provider { base, refreshes }
}

fn start(dir: &Path, args: &[&str], ready: &str) -> (Guard, String) {
    let mut child = Command::new(env!("CARGO_BIN_EXE_ant"))
        .args(args)
        .current_dir(dir)
        .stdout(Stdio::piped())
        .stderr(Stdio::null())
        .spawn()
        .expect("spawn");
    let mut line = String::new();
    BufReader::new(child.stdout.take().expect("stdout"))
        .read_line(&mut line)
        .expect("read");
    assert!(line.contains(ready), "{line}");
    (Guard(child), line)
}

#[test]
fn single_sign_on_with_the_device_flow() {
    let dir = TempDir::new("flow");
    let key_path = dir.0.join("idp.pem");
    let made = Command::new("openssl")
        .args([
            "genpkey",
            "-algorithm",
            "RSA",
            "-pkeyopt",
            "rsa_keygen_bits:2048",
            "-out",
        ])
        .arg(&key_path)
        .output()
        .is_ok_and(|output| output.status.success());
    if !made {
        assert!(std::env::var_os("CI").is_none(), "openssl is needed in CI");
        eprintln!("skipping: openssl not available");
        return;
    }
    let modulus_line = Command::new("openssl")
        .args(["rsa", "-noout", "-modulus", "-in"])
        .arg(&key_path)
        .output()
        .expect("modulus");
    let hex = String::from_utf8_lossy(&modulus_line.stdout)
        .trim()
        .trim_start_matches("Modulus=")
        .to_owned();
    let modulus: Vec<u8> = (0..hex.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&hex[i..i + 2], 16).expect("hex"))
        .collect();
    let pem = std::fs::read_to_string(&key_path).expect("pem");
    let der = base64::engine::general_purpose::STANDARD
        .decode(
            pem.lines()
                .filter(|line| !line.starts_with("-----"))
                .collect::<String>(),
        )
        .expect("der");
    let key = Arc::new(ring::signature::RsaKeyPair::from_pkcs8(&der).expect("key"));
    let provider = fake_provider(key.clone(), modulus);

    for (name, token) in [
        (
            "client.token",
            "client-token-0123456789abcdefghijklmnopqrstuv",
        ),
        (
            "worker.token",
            "worker-token-0123456789abcdefghijklmnopqrstuv",
        ),
    ] {
        std::fs::write(dir.0.join(name), token).expect("token");
    }
    let (_coordinator, line) = start(
        &dir.0,
        &[
            "coordinator",
            "--listen",
            "127.0.0.1:0",
            "--data-dir",
            "coord",
            "--client-token-file",
            "client.token",
            "--worker-token-file",
            "worker.token",
            "--oidc-issuer",
            &provider.base,
            "--oidc-client-id",
            "ant-test",
            "--oidc-allowed-domains",
            "acme.dev",
        ],
        "listening=",
    );
    let address = line
        .split_whitespace()
        .find_map(|part| part.strip_prefix("listening="))
        .expect("address")
        .to_owned();
    let url = format!("http://{address}");
    let worker = Command::new(env!("CARGO_BIN_EXE_ant"))
        .args([
            "worker",
            "--coordinator",
            &url,
            "--token-file",
            "worker.token",
            "--work-dir",
            "work",
        ])
        .current_dir(&dir.0)
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .spawn()
        .expect("worker");
    let _worker = Guard(worker);

    let data = dir.0.join("data");
    let ant = |args: &[&str]| {
        let output = Command::new(env!("CARGO_BIN_EXE_ant"))
            .current_dir(&dir.0)
            .env("ANT_DATA_HOME", &data)
            .env("ANT_CACHE_HOME", data.join("cache"))
            .args(args)
            .output()
            .expect("spawn ant");
        (
            output.status.code().unwrap_or(-1),
            String::from_utf8_lossy(&output.stdout).into_owned(),
            String::from_utf8_lossy(&output.stderr).into_owned(),
        )
    };
    let (code, stdout, stderr) = ant(&["login", &url, "--sso", "--name", "team"]);
    assert_eq!(code, 0, "{stdout}{stderr}");
    assert!(stdout.contains("enter the code:  ABCD-EFGH"), "{stdout}");
    assert!(stdout.contains("Signed in to team"), "{stdout}");

    // A real job with the signed-in identity; the short-lived ID token is
    // renewed first with the refresh token.
    let plan = serde_json::json!({ "schema_version": 1, "actions": [{ "action": {
        "schema_version": 1, "id": "hello",
        "argv": if cfg!(windows) { serde_json::json!(["cmd", "/C", "echo hi> out.txt"]) } else { serde_json::json!(["sh", "-c", "echo hi > out.txt"]) },
        "working_directory": ".", "inputs": [], "outputs": [{ "path": "out.txt", "kind": "file" }],
        "environment": [], "cache_policy": "never" }, "dependencies": [] }]});
    std::fs::write(dir.0.join("plan.json"), plan.to_string()).expect("plan");
    let (code, stdout, stderr) = ant(&[
        "remote",
        "run",
        "--server",
        "team",
        "--plan",
        "plan.json",
        "--workspace",
        ".",
    ]);
    assert_eq!(code, 0, "{stdout}{stderr}");
    assert_eq!(
        std::fs::read_to_string(dir.0.join("out.txt"))
            .expect("out")
            .trim(),
        "hi"
    );
    assert_eq!(
        provider.refreshes.load(Ordering::SeqCst),
        1,
        "renewed before expiry"
    );
    let (code, stdout, _) = ant(&["server", "audit", "team"]);
    assert_eq!(code, 0);
    let audit = std::fs::read_to_string(dir.0.join("coord").join("audit.jsonl")).expect("audit");
    assert!(
        audit
            .lines()
            .any(|line| line.contains("job_submitted") && line.contains("dev@acme.dev")),
        "{audit}\n{stdout}"
    );

    // Refused: another domain, a forged signature, another audience.
    let client = |token: &str| {
        Command::new("curl")
            .args(["-s", "-o", "/dev/null", "-w", "%{http_code}", "-H"])
            .arg(format!("Authorization: Bearer {token}"))
            .arg(format!("{url}/v1/jobs"))
            .output()
            .map(|output| String::from_utf8_lossy(&output.stdout).into_owned())
    };
    let good = id_token(
        &key,
        &provider.base,
        "ant-test",
        "dev@acme.dev",
        now() + 600,
    );
    if let Ok(status) = client(&good) {
        assert_eq!(status, "200");
        let outsider = id_token(
            &key,
            &provider.base,
            "ant-test",
            "eve@other.org",
            now() + 600,
        );
        assert_eq!(client(&outsider).expect("curl"), "401");
        let other_app = id_token(
            &key,
            &provider.base,
            "someone-else",
            "dev@acme.dev",
            now() + 600,
        );
        assert_eq!(client(&other_app).expect("curl"), "401");
        let mut forged = good.clone();
        forged.replace_range(forged.len() - 6.., "AAAAAA");
        assert_eq!(client(&forged).expect("curl"), "401");
        let audit =
            std::fs::read_to_string(dir.0.join("coord").join("audit.jsonl")).expect("audit");
        assert!(
            audit.contains("this email domain is not allowed"),
            "{audit}"
        );
        assert!(audit.contains("issued for another application"));
    }
}
